const CACHE_NAME = 'studyos-tce-go-o2-v1';
const APP_SHELL = ['./', './index.html', './styles.css', './app.js', './site-app.js?o2=1', './manifest.webmanifest', './icon.svg', './release-diagnostics.html', './release-diagnostics.js', './o1-diagnostics.html', './o1-diagnostics.js', './core/src/index.js', './core/src/storage.js', './core/src/scoring.js', './core/src/gamification.js', './core/src/mastery.js', './core/src/diagnostics.js', './core/src/diagnostic-ui.js', './core/src/today-planner.js', './core/src/today-ui.js', './exam-pack/manifest.json', './exam-pack/facts.json', './exam-pack/source-map.json', './exam-pack/curriculum.json', './exam-pack/resources.json', './exam-pack/questions.json', './exam-pack/study-plan.json', './exam-pack/content-coverage.json', './exam-pack/flashcards.json', './exam-pack/simulations.json'];
self.addEventListener('install', (event) => { event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(APP_SHELL))); self.skipWaiting(); });
self.addEventListener('activate', (event) => { event.waitUntil(Promise.all([self.clients.claim(), caches.keys().then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))))])); });
self.addEventListener('fetch', (event) => { event.respondWith(caches.open(CACHE_NAME).then((cache) => cache.match(event.request)).then((cached) => cached || fetch(event.request))); });
